// Breadth parity with the Python memcalc: web/test/fixtures/memcalc_vectors.json is generated by
// serve/scripts/memcalc_web_vectors.py (Python). The TS port must reproduce every per-layer spec, parameter
// bucket, sequence size and estimate field. Integers must match exactly; floats to 1e-12 relative.
import assert from "node:assert/strict";
import path from "node:path";
import { describe, it } from "node:test";
import { fileURLToPath } from "node:url";
import { estimate, seqBytes, type Components } from "../src/lib/memcalc/calc.ts";
import { getDevice } from "../src/lib/memcalc/devices.ts";
import { PARAM_BUCKETS, type ModelSpec } from "../src/lib/memcalc/model.ts";
import { loadDevices, loadFixtureModel, readJson } from "../src/lib/repo.ts";

interface PyLayer {
  index: number;
  kind: string;
  q_heads: number;
  kv_heads: number;
  head_dim: number;
  window: number | null;
  shares_from: number | null;
  state_elems: number;
  state_dtype_bytes: number;
  conv_elems: number;
  conv_dtype_bytes: number;
}
interface Vectors {
  ctxs: number[];
  models: Record<
    string,
    {
      name: string;
      params: Record<string, number | string>;
      moe: { num_experts: number; experts_per_token: number } | null;
      layers: PyLayer[];
      seq_bytes: Record<string, number[]>;
    }
  >;
  estimates: {
    model: string;
    device: string;
    args: {
      weight_fmt: string;
      kv_fmt: string;
      ctx: number;
      util: number;
      reserve_gib?: number;
      components?: Components;
      ple_offload?: boolean;
      with_mtp?: boolean;
    };
    expect: Record<string, unknown>;
  }[];
}

const here = path.dirname(fileURLToPath(import.meta.url));
const V = readJson<Vectors>(path.join(here, "fixtures", "memcalc_vectors.json"));
const DEVICES = loadDevices();
const specs = new Map<string, ModelSpec>();
const spec = (name: string): ModelSpec => {
  if (!specs.has(name)) specs.set(name, loadFixtureModel(name));
  return specs.get(name)!;
};
const snake = (k: string): string => k.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);

function close(actual: unknown, expected: unknown, where: string): void {
  if (typeof expected === "number" && typeof actual === "number") {
    if (Number.isInteger(expected) && Number.isInteger(actual)) {
      assert.equal(actual, expected, where);
    } else {
      const tol = 1e-12 * Math.max(1, Math.abs(expected));
      assert.ok(Math.abs(actual - expected) <= tol, `${where}: ${actual} != ${expected}`);
    }
    return;
  }
  assert.deepEqual(actual, expected, where);
}

describe("model specs match Python", () => {
  for (const [dir, m] of Object.entries(V.models)) {
    it(dir, () => {
      const s = spec(dir);
      assert.equal(s.name, m.name);
      for (const b of PARAM_BUCKETS) close(s.params[b], m.params[snake(b)], `${dir} params.${b}`);
      assert.equal(s.params.source, m.params["source"]);
      assert.deepEqual(
        s.moe && { num_experts: s.moe.numExperts, experts_per_token: s.moe.expertsPerToken },
        m.moe,
        `${dir} moe`,
      );
      assert.equal(s.layers.length, m.layers.length);
      s.layers.forEach((l, i) => {
        const p = m.layers[i]!;
        const ts = {
          index: l.index,
          kind: l.kind,
          q_heads: l.qHeads,
          kv_heads: l.kvHeads,
          head_dim: l.headDim,
          window: l.window,
          shares_from: l.sharesFrom,
          state_elems: l.stateElems,
          state_dtype_bytes: l.stateDtypeBytes,
          conv_elems: l.convElems,
          conv_dtype_bytes: l.convDtypeBytes,
        };
        assert.deepEqual(ts, p, `${dir} layer ${i}`);
      });
      for (const [kv, values] of Object.entries(m.seq_bytes)) {
        V.ctxs.forEach((ctx, i) => assert.equal(seqBytes(s, ctx, kv), values[i], `${dir} seq_bytes ${kv} @${ctx}`));
      }
    });
  }
});

describe("estimates match Python", () => {
  V.estimates.forEach((c, n) => {
    const a = c.args;
    it(`${n}: ${c.model} on ${c.device} ${a.weight_fmt}/${a.kv_fmt} @${a.ctx}`, () => {
      const est = estimate(spec(c.model), getDevice(DEVICES, c.device), {
        weightFmt: a.weight_fmt,
        kvFmt: a.kv_fmt,
        ctx: a.ctx,
        util: a.util,
        reserveGib: a.reserve_gib ?? null,
        components: a.components ?? "text",
        pleOffload: a.ple_offload ?? false,
        withMtp: a.with_mtp ?? false,
      });
      const got = est as unknown as Record<string, unknown>;
      assert.deepEqual(Object.keys(got).sort(), Object.keys(c.expect).sort(), "field set");
      for (const [k, v] of Object.entries(c.expect)) close(got[k], v, k);
    });
  });
});
